DO $$
DECLARE
  target_rep uuid;
BEGIN
  -- Fetch Bourhane ID
  SELECT id INTO target_rep FROM public.profiles WHERE email = 'bourhane.fetni7009@gmail.com' LIMIT 1;
  IF target_rep IS NULL THEN
    SELECT id INTO target_rep FROM auth.users WHERE email = 'bourhane.fetni7009@gmail.com' LIMIT 1;
  END IF;
  IF target_rep IS NULL THEN
    SELECT id INTO target_rep FROM public.profiles LIMIT 1;
  END IF;

END $$;
